export const getExportGiftcardsCsvUrl = (params?: ExportGiftcardsCsvParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/carte-cadeau-api/admin/cards/export?${stringifiedParams}` : `/carte-cadeau-api/admin/cards/export`
}

